defmodule JoobQ.Workflow.RefTest do
  use ExUnit.Case, async: true

  alias JoobQ.Workflow.Ref

  test "references are the gateway's ${...} paths, keys as atoms, strings, dotted paths or list indexes" do
    assert Ref.input(nil).expr == "${input}"
    assert Ref.input(:sku).expr == "${input.sku}"
    assert Ref.input("order.items").expr == "${input.order.items}"
    assert Ref.input(0).expr == "${input.0}"
    assert Ref.output("reserve", nil).expr == "${steps.reserve.output}"
    assert Ref.output("reserve", "id").expr == "${steps.reserve.output.id}"
    assert Ref.update_input("street").expr == "${update.input.street}"
    assert Ref.ref("signals.approve").expr == "${signals.approve}"
    assert Ref.ref("${updates.rename}").expr == "${updates.rename}"
  end

  test "a key or step name that could escape its segment is refused, without its value" do
    for bad <- [
          fn -> Ref.input("a}b") end,
          fn -> Ref.input("a b") end,
          fn -> Ref.input("é") end,
          fn -> Ref.input("a..b") end,
          fn -> Ref.input(-1) end,
          fn -> Ref.input(%{"secret" => 1}) end,
          fn -> Ref.output("a.b", nil) end,
          fn -> Ref.output(:step, nil) end,
          fn -> Ref.ref("${secret}") end,
          fn -> Ref.ref("input.a} ${steps") end
        ] do
      error = assert_raise ArgumentError, bad
      refute error.message =~ "secret"
    end
  end

  test "references are collected once each, maps walked by sorted key, so the order never depends on the map" do
    keys = for n <- 1..40, do: "k#{String.pad_leading("#{n}", 2, "0")}"
    spec = Map.new(Enum.shuffle(keys), &{&1, Ref.input(&1)})
    assert Ref.references(spec) == Enum.map(keys, &"${input.#{&1}}")

    spec = %{
      b: Ref.output("s2", "x"),
      a: [Ref.output("s1", nil), Ref.output("s1", nil)],
      c: "literal"
    }

    assert Ref.references(spec) == ["${steps.s1.output}", "${steps.s2.output.x}"]
    assert Ref.steps(spec) == ["s1", "s2"]
    assert Ref.references(nil) == []
  end

  test "keyword lists and tuples are walked; a reference inside a struct or an improper list is refused" do
    spec = [sku: Ref.input("sku"), pair: {Ref.output("a", nil), 1}]
    assert Ref.references(spec) == ["${input.sku}", "${steps.a.output}"]
    assert Ref.steps([{:x, Ref.output("nope", nil)}]) == ["nope"]
    assert Ref.references(%{at: ~D[2026-01-01], uri: URI.parse("https://secret.example")}) == []

    for bad <- [%{wrap: %URI{host: Ref.input("secret")}}, [Ref.input("a") | Ref.input("secret")]] do
      error = assert_raise ArgumentError, fn -> Ref.references(bad) end
      refute error.message =~ "secret"
    end
  end

  test "paths the engine reads differently are refused: a step without .output, a negative index" do
    for bad <- ["steps.reserve", "steps.reserve.id", "${steps}", "updates", "input.items.-1"] do
      assert_raise ArgumentError, ~r/ref\/1/, fn -> Ref.ref(bad) end
    end

    assert_raise ArgumentError, ~r/negative index/, fn -> Ref.input("items.-1") end
    assert Ref.ref("steps.reserve.output.-x").expr == "${steps.reserve.output.-x}"
    assert Ref.ref("updates.rename").expr == "${updates.rename}"
  end
end
